<?php
declare(strict_types=1);require dirname(__DIR__).'/bootstrap.php';$user=requireUser($pdo);
if($_SERVER['REQUEST_METHOD']==='POST'){$d=input();foreach(['title','excerpt','content'] as $field){if(strlen(trim($d[$field]??''))<3){http_response_code(422);exit(json_encode(['error'=>"$field is required."]));}}$slug=slugify($d['slug']??$d['title']).'-'.substr(bin2hex(random_bytes(3)),0,6);$cat=$pdo->prepare('SELECT id FROM categories WHERE name=? LIMIT 1');$cat->execute([$d['category']??'Technology']);$status=!empty($d['publish'])?'published':'draft';$q=$pdo->prepare('INSERT INTO posts(category_id,user_id,slug,title,excerpt,image_url,content,author,status,published_at) VALUES(?,?,?,?,?,?,?,?,?,IF(?="published",NOW(),NULL))');$q->execute([$cat->fetchColumn()?:null,$user['id'],$slug,trim($d['title']),trim($d['excerpt']),trim($d['image_url']??''),trim($d['content']),$user['name'],$status,$status]);$refresh=$status==='published'?publishedContentChanged($pdo,$config,$slug):['sitemap_updated'=>false,'deployment_queued'=>false];http_response_code(201);exit(json_encode(['ok'=>true,'slug'=>$slug,'message'=>$status==='published'?'Your post is now live.':'Your draft was submitted for editorial review.']+$refresh));}
if($_SERVER['REQUEST_METHOD']==='DELETE'){$id=(int)($_GET['id']??0);$q=$pdo->prepare('DELETE FROM posts WHERE id=? AND user_id=? AND status="draft"');$q->execute([$id,$user['id']]);exit(json_encode(['ok'=>true]));}
http_response_code(405);echo json_encode(['error'=>'Method not allowed.']);
